// ---------------------------------------------------------------------------
// Shared result assembly (client.py execute semantics)
// ---------------------------------------------------------------------------

fn error_value(category: &str, message: String) -> Value {
    json!({
        "provider": "goofish",
        "ok": false,
        "error": {"message": message, "category": category},
    })
}

fn halted_value(category: &str) -> Value {
    json!({
        "provider": "goofish",
        "ok": false,
        "error": {
            "message": format!(
                "sending halted after a {category} response; call reset_send_halt() to resume"
            ),
            "category": "send_halted",
            "halted_by": category,
        },
    })
}

/// Refusals that must happen before any transport use: unknown API,
/// login-required API, or no parser registered.
pub fn preflight_error(plan: &RequestPlan) -> Option<Value> {
    match registry::get_api(&plan.api_name) {
        Ok(spec) => {
            if spec.is_login_required() {
                let reason = spec
                    .excluded_reason
                    .map(|r| format!(" ({r})"))
                    .unwrap_or_default();
                return Some(error_value(
                    classify::CATEGORY_LOGIN_REQUIRED,
                    format!(
                        "API {} requires login and is out of scope for anonymous browsing{reason}",
                        plan.api_name
                    ),
                ));
            }
        }
        Err(e) => {
            return Some(error_value(classify::CATEGORY_API_NOT_FOUND, e.to_string()));
        }
    }
    if !parse::parser_supported(&plan.api_name) {
        return Some(error_value(
            classify::CATEGORY_API_ERROR,
            format!("no parser registered for {}", plan.api_name),
        ));
    }
    None
}

fn finish_response(
    status: u16,
    body: &Value,
    plan: &RequestPlan,
    halt: &Mutex<Option<String>>,
) -> Value {
    let normalized = parse::parse_mtop_envelope(body).unwrap_or_else(|_| json!({}));
    let ret = normalized.get("ret").cloned().unwrap_or_else(|| json!([]));
    let ret_code = normalized.get("ret_code").cloned().unwrap_or(Value::Null);
    let category = classify::classify_mtop_response(status, &ret);
    let detailed_error = |category: &str, message: String| -> Value {
        json!({
            "provider": "goofish",
            "ok": false,
            "error": {
                "message": message,
                "category": category,
                "ret": ret,
                "status": status,
                "ret_code": ret_code,
            },
        })
    };
    if classify::is_typed_error_category(category) {
        if classify::is_restriction(category) {
            *halt.lock().unwrap() = Some(category.to_string());
        }
        let message = parse::envelope_error(&normalized).to_string();
        return detailed_error(category, message);
    }
    if category == classify::CATEGORY_SUCCESS {
        let data = normalized.get("data").cloned().unwrap_or(Value::Null);
        if !data.is_object() {
            return error_value(
                "parse_error",
                "SUCCESS response data is not a JSON object".to_string(),
            );
        }
        return match parse::parse_for_api(&plan.api_name, body) {
            Ok(parsed) => json!({
                "provider": "goofish",
                "ok": true,
                "api": plan.api_name,
                "version": plan.version,
                "data": parsed,
            }),
            Err(e) => error_value("parse_error", e.to_string()),
        };
    }
    // business_error / api_error / unknown: the Python parsers raise the
    // envelope error for a non-SUCCESS ret.
    let message = parse::envelope_error(&normalized).to_string();
    detailed_error(category, message)
}

// ---------------------------------------------------------------------------
// Offline core client (Transport-generic)
// ---------------------------------------------------------------------------

pub struct CoreClient<T: Transport> {
    pub transport: T,
    halt: Mutex<Option<String>>,
}

impl<T: Transport> CoreClient<T> {
    pub fn new(transport: T) -> Self {
        Self {
            transport,
            halt: Mutex::new(None),
        }
    }

    pub fn reset_send_halt(&self) {
        *self.halt.lock().unwrap() = None;
    }

    pub fn halted_by(&self) -> Option<String> {
        self.halt.lock().unwrap().clone()
    }

    pub fn execute(&self, plan: &RequestPlan) -> Value {
        if let Some(err) = preflight_error(plan) {
            return err;
        }
        if let Some(category) = self.halt.lock().unwrap().clone() {
            return halted_value(&category);
        }
        match self.transport.execute(plan) {
            Ok((status, body)) => finish_response(status, &body, plan, &self.halt),
            Err(e) => error_value("transport_error", e.to_string()),
        }
    }

    /// Search pagination (client.py `paginate_search` rules): request
    /// the next page only while the previous page parsed with
    /// `has_next_page == true` and advanced the pagination state; stop
    /// when the next plan's data is identical to the current one or the
    /// non-paging condition fingerprint changes. At most 50 pages.
    pub fn paginate_search(&self, first_plan: &RequestPlan) -> Value {
        let mut pagination = SearchPagination::new();
        let mut plan = first_plan.clone();
        let mut pages: Vec<Value> = Vec::new();
        let mut items: Vec<Value> = Vec::new();
        for _ in 0..50 {
            let result = self.execute(&plan);
            if result.get("ok").and_then(|v| v.as_bool()) != Some(true) {
                return result;
            }
            let parsed = result.get("data").cloned().unwrap_or_else(|| json!({}));
            if let Some(arr) = parsed.get("items").and_then(|v| v.as_array()) {
                items.extend(arr.iter().cloned());
            }
            pages.push(parsed.clone());
            if !pagination.advance(&parsed) {
                break;
            }
            let next = plan.with_fields(&pagination.request_fields());
            if next.data == plan.data {
                break;
            }
            if condition_fingerprint(&next) != condition_fingerprint(&plan) {
                break;
            }
            plan = next;
        }
        json!({
            "provider": "goofish",
            "ok": true,
            "page_count": pages.len(),
            "pages": pages,
            "items": items,
        })
    }
}

/// Canonical fingerprint of a search plan's non-paging conditions
/// (data minus the SearchPagination-controlled fields, keys sorted).
fn condition_fingerprint(plan: &RequestPlan) -> String {
    let mut map = BTreeMap::new();
    if let Some(obj) = plan.data.as_object() {
        for (k, v) in obj {
            if !SEARCH_PAGING_FIELDS.contains(&k.as_str()) {
                map.insert(k.clone(), v.clone());
            }
        }
    }
    serde_json::to_string(&Value::Object(
        map.into_iter().collect::<Map<String, Value>>(),
    ))
    .unwrap_or_default()
}

// ---------------------------------------------------------------------------
// Live client
// ---------------------------------------------------------------------------

const IDENTITY_ENVS: [&str; 2] = ["GOOFISH_IDENTITY", "SHOPPING_MCP_GOOFISH_IDENTITY"];
const SERVE_ENVS: [&str; 2] = ["GOOFISH_SG_SERVE", "SHOPPING_MCP_GOOFISH_SG_SERVE"];
const CONFIG_ENVS: [&str; 1] = ["SHOPPING_MCP_GOOFISH_CONFIG"];
const DEFAULT_FEATURES: &str = "27";
const DEFAULT_APP_VERSION: &str = "7.28.70";
const DEFAULT_PV: &str = "6.2";

/// Per-sign-request budget once the harness is warm.
const SIGN_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(300);
/// Harness startup budget (spawn -> ready line), kept separate from
/// the sign budget. Startup is dominated by the SecurityGuard 10101
/// init running under unicorn2 emulation — in particular the phase
/// that processes the staged 268MB APK — so its wall time tracks
/// the host's per-core emulation throughput: measured ~150-180s on
/// an idle VM (round 19, 2026-10-31) but ~420-460s on 2026-11-07
/// with several other JVM/unidbg workloads on the same 4 cores.
/// The previous single 300s budget killed two ZeroSearch attempts
/// inside that init phase (the harness main thread was still
/// RUNNABLE in emu_start; nothing had been sent). 900s is ~2x the
/// worst measured startup and ~5x the idle measurement.
const STARTUP_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(900);

fn build_signer(serve_command: &[String]) -> Result<UnidbgSigner, String> {
    UnidbgSigner::with_timeouts(serve_command.to_vec(), SIGN_TIMEOUT, STARTUP_TIMEOUT, false)
        .map_err(|e| e.to_string())
}

pub struct GoofishClient {
    halt: Mutex<Option<String>>,
    signer: Mutex<Option<UnidbgSigner>>,
}

impl Default for GoofishClient {
    fn default() -> Self {
        Self::new()
    }
}

/// Per-call phase breakdown and network diagnostics attached to
/// live results as `timings_ms` / `diagnostics` (issue #2): callers
/// must be able to tell a slow harness start from a dead connection
/// without re-running anything.
struct CallMeta {
    started: Instant,
    signer_startup_ms: Option<u128>,
    sign_ms: Option<u128>,
    post_ms: Option<u128>,
    post_attempts: u32,
    proxy: netdiag::ProxyDiagnostic,
}

impl CallMeta {
    fn new(started: Instant) -> Self {
        Self {
            started,
            signer_startup_ms: None,
            sign_ms: None,
            post_ms: None,
            post_attempts: 0,
            proxy: netdiag::proxy_diagnostic(),
        }
    }

    fn attach(&self, mut value: Value) -> Value {
        if value.is_object() {
            value["timings_ms"] = json!({
                "signer_startup": self.signer_startup_ms,
                "sign": self.sign_ms,
                "post": self.post_ms,
                "total": self.started.elapsed().as_millis(),
            });
            value["diagnostics"] = json!({
                "proxy": self.proxy.to_json(),
                "post_attempts": self.post_attempts,
            });
        }
        value
    }
}

impl Drop for GoofishClient {
    /// Dropping the client must shut the signing harness down, not
    /// orphan it (issue #2).
    fn drop(&mut self) {
        if let Ok(mut guard) = self.signer.lock() {
            if let Some(signer) = guard.take() {
                signer.close();
                drop(signer);
            }
        }
    }
}

impl GoofishClient {
    pub fn new() -> Self {
        Self {
            halt: Mutex::new(None),
            signer: Mutex::new(None),
        }
    }

    /// Pre-warm: resolve the runtime and start the signing harness
    /// now, so the first live call does not pay the whole startup
    /// (measured in minutes; see STARTUP_TIMEOUT). Best-effort and
    /// local-only — no network access, no MTOP send. Returns true
    /// when the harness is started (or was already running). Any
    /// failure is latched in the signer and surfaces, unchanged, on
    /// the first real call.
    pub fn warm_up(&self) -> bool {
        let runtime = resolve_runtime();
        let Some(serve_path) = runtime.serve_command else {
            return false;
        };
        let serve_command = split_serve_command(&serve_path);
        if serve_command.is_empty() {
            return false;
        }
        let mut guard = self.signer.lock().unwrap();
        if guard.is_none() {
            match build_signer(&serve_command) {
                Ok(signer) => *guard = Some(signer),
                Err(_) => return false,
            }
        }
        guard
            .as_ref()
            .map(|signer| signer.ensure_started().is_ok())
            .unwrap_or(false)
    }

    pub fn reset_send_halt(&self) {
        *self.halt.lock().unwrap() = None;
    }

    pub fn halted_by(&self) -> Option<String> {
        self.halt.lock().unwrap().clone()
    }

    async fn execute_live(&self, plan: &RequestPlan) -> Value {
        if let Some(err) = preflight_error(plan) {
            return err;
        }
        if let Some(category) = self.halt.lock().unwrap().clone() {
            return halted_value(&category);
        }
        let mut meta = CallMeta::new(Instant::now());
        // -- Resolve the local runtime BEFORE any network access.
        let mut missing: Vec<String> = Vec::new();
        let runtime = resolve_runtime();
        let identity_path = runtime.identity_path;
        let serve_path = runtime.serve_command;
        let mut utdid = String::new();
        let mut device_id: Option<String> = None;
        let mut ttid = String::new();
        match &identity_path {
            None => missing.push(
                "identity file (normally generated automatically by the server into its \
                 data directory; GOOFISH_IDENTITY / SHOPPING_MCP_GOOFISH_IDENTITY or an \
                 \"identity\" entry in the Goofish config file can override it)"
                    .to_string(),
            ),
            Some(path) => {
                let parsed = std::fs::read_to_string(path)
                    .ok()
                    .and_then(|text| serde_json::from_str::<Value>(&text).ok())
                    .filter(|v| v.is_object());
                match parsed {
                    Some(doc) => {
                        utdid = doc
                            .get("utdid")
                            .and_then(crate::util::as_str)
                            .unwrap_or_default();
                        if utdid.is_empty() {
                            missing.push("utdid".to_string());
                        }
                        device_id = doc.get("device_id").and_then(crate::util::as_str);
                        if device_id.is_none() {
                            missing.push("device_id".to_string());
                        }
                        ttid = doc
                            .get("ttid")
                            .and_then(crate::util::as_str)
                            .unwrap_or_default();
                    }
                    None => missing.push(format!(
                        "identity file at {} (unreadable or not a JSON object)",
                        path
                    )),
                }
            }
        }
        if serve_path.is_none() {
            missing.push(
                "signer serve command (no goofish-runtime bundle found next to the server \
                 executable or in its data directory; GOOFISH_SG_SERVE / \
                 SHOPPING_MCP_GOOFISH_SG_SERVE or \"sg_serve\" in the Goofish config file \
                 can point at one explicitly)"
                    .to_string(),
            );
        }
        if !missing.is_empty() {
            return meta.attach(error_value(
                "missing_runtime",
                format!("missing runtime pieces: {}", missing.join(", ")),
            ));
        }
        let serve_path = serve_path.unwrap();
        // The setting is a *command*: it may carry arguments and
        // quoting, not just a bare executable path (issue #1).
        let serve_command = split_serve_command(&serve_path);
        if serve_command.is_empty() {
            return meta.attach(error_value(
                "missing_runtime",
                "signer serve command is empty after parsing".to_string(),
            ));
        }
        // -- Sign (synchronous; the signer process is Mutex-guarded).
        let sign_started = Instant::now();
        let (sign_result, timestamp) = {
            let mut guard = self.signer.lock().unwrap();
            if guard.is_none() {
                match build_signer(&serve_command) {
                    Ok(signer) => *guard = Some(signer),
                    Err(e) => return meta.attach(error_value("signing_error", e)),
                }
            }
            let signer = guard.as_ref().unwrap();
            let was_started = signer.is_started();
            // Start the harness BEFORE taking the request
            // timestamp (K1-4): a cold start takes minutes, and a
            // `t` captured before it is stale by the time the
            // request is posted — MTOP validates `t` as part of
            // the sign. The first ZeroSearch live call carried a
            // ~426s-old `t` (the sign phase waited out the whole
            // startup) and was rejected FAIL_SYS_ILEGEL_SIGN.
            // Taking the timestamp after ensure_started makes the
            // cold first call behave like the real client, which
            // stamps at send time; warm calls are unaffected (the
            // ensure is a no-op and the stamp was already fresh).
            if let Err(e) = signer.ensure_started() {
                return meta.attach(error_value("signing_error", e.to_string()));
            }
            let timestamp = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .map(|d| d.as_secs().to_string())
                .unwrap_or_default();
            let mut request = SignRequest::new(
                &plan.api_name,
                &plan.version,
                plan.data_json(),
                timestamp.clone(),
            );
            request.utdid = Some(utdid.clone());
            request.device_id = device_id.clone();
            request.ttid = if ttid.is_empty() {
                None
            } else {
                Some(ttid.clone())
            };
            request.x_features = Some(DEFAULT_FEATURES.to_string());
            let result = signer.sign(&request);
            if !was_started {
                meta.signer_startup_ms = signer.last_startup_duration().map(|d| d.as_millis());
            }
            (result, timestamp)
        };
        meta.sign_ms = Some(sign_started.elapsed().as_millis());
        let sign_result = match sign_result {
            Ok(result) => result,
            Err(e) => return meta.attach(error_value("signing_error", e.to_string())),
        };

        // -- Assemble the wire form.
        let ctx = RuntimeContext {
            sign: Some(sign_result.sign.clone()),
            timestamp: Some(timestamp),
            utdid: Some(utdid),
            device_id,
            umid_token: sign_result.x_umt.clone(),
            sid: None,
            uid: None,
            ttid: if ttid.is_empty() { None } else { Some(ttid) },
            pv: Some(DEFAULT_PV.to_string()),
            features: Some(DEFAULT_FEATURES.to_string()),
            app_version: Some(DEFAULT_APP_VERSION.to_string()),
        };
        let assembled = match protocol::build_form(plan, Some(&ctx)) {
            Ok(v) => v,
            Err(e) => return meta.attach(error_value("missing_runtime", e.to_string())),
        };
        let url_path = assembled
            .get("url_path")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let data_json = assembled
            .pointer("/form/data")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();

        // -- POST. reqwest's env-proxy handling stays ON (the
        // workspace enables the system-proxy / socks features
        // explicitly, issue #2; see `diagnostics.proxy` in the
        // result for what was detected at runtime).
        //
        // Timeouts are split (issue #2, item 6): the connect timeout
        // is 15s so a connection-establishment failure — the only
        // retryable kind — surfaces quickly instead of consuming the
        // whole request budget, while the overall per-attempt
        // timeout stays at the historical 60s.
        let client = match reqwest::Client::builder()
            .redirect(reqwest::redirect::Policy::none())
            .connect_timeout(Duration::from_secs(15))
            .build()
        {
            Ok(c) => c,
            Err(e) => {
                return meta.attach(error_value(
                    "transport_error",
                    netdiag::format_error_chain(&e),
                ))
            }
        };
        // Retry policy (issue #2, item 3): at most 2 retries, and
        // only for connection-establishment failures, where no
        // response was or could be received. Identical request,
        // identical identity/session — nothing is varied. Any HTTP
        // response, including restriction statuses (419/403/429),
        // ends the loop and is handled by finish_response as before.
        const MAX_CONNECT_RETRIES: u32 = 2;
        let post_started = Instant::now();
        let mut attempt: u32 = 0;
        let response = loop {
            attempt += 1;
            meta.post_attempts = attempt;
            let mut request = client
                .post(format!("{}{}", protocol::GATEWAY_PRIMARY, url_path))
                .header(
                    "Content-Type",
                    "application/x-www-form-urlencoded;charset=UTF-8",
                )
                .timeout(Duration::from_secs(60))
                .body(format!("data={}", percent_encode(&data_json)));
            if let Some(headers) = assembled.get("headers").and_then(|h| h.as_object()) {
                for (name, value) in headers {
                    if let Some(value) = value.as_str() {
                        request = request.header(name.as_str(), value);
                    }
                }
            }
            if let Some(wua) = &sign_result.x_mini_wua {
                if !wua.is_empty() {
                    request = request.header("x-mini-wua", wua.as_str());
                }
            }
            if let Some(sgext) = &sign_result.x_sgext {
                if !sgext.is_empty() {
                    request = request.header("x-sgext", sgext.as_str());
                }
            }
            match request.send().await {
                Ok(r) => break Ok(r),
                Err(e) => {
                    let info = netdiag::classify_reqwest_error(&e);
                    if info.connect_phase && attempt <= MAX_CONNECT_RETRIES {
                        let backoff = if attempt == 1 {
                            Duration::from_secs(1)
                        } else {
                            Duration::from_secs(3)
                        };
                        tokio::time::sleep(backoff).await;
                        continue;
                    }
                    let mut err = error_value(info.category, netdiag::format_error_chain(&e));
                    err["error"]["source_chain"] = json!(info.chain);
                    err["error"]["connect_phase"] = json!(info.connect_phase);
                    break Err(err);
                }
            }
        };
        meta.post_ms = Some(post_started.elapsed().as_millis());
        let response = match response {
            Ok(r) => r,
            Err(err_value) => return meta.attach(err_value),
        };
        let status = response.status().as_u16();
        let text = response.text().await.unwrap_or_default();
        let body: Value = match serde_json::from_str::<Value>(&text) {
            Ok(v) if v.is_object() => v,
            _ => {
                return meta.attach(json!({
                    "provider": "goofish",
                    "ok": false,
                    "error": {
                        "message": "response body is not a JSON object",
                        "category": "response_decode_error",
                        "status": status,
                    },
                }))
            }
        };
        meta.attach(finish_response(status, &body, plan, &self.halt))
    }

    /// Search products. `sort`: "create" (newest first), "credit",
    /// "price_asc", "price_desc" — mapped to the app's sortField /
    /// sortValue pair. A sorted search is expected to draw a 419
    /// verification response live; it is surfaced, not hidden.
    pub async fn search_products(
        &self,
        query: &str,
        page: i64,
        limit: i64,
        sort: Option<&str>,
        price_min: Option<&str>,
        price_max: Option<&str>,
    ) -> Value {
        let mut filters = SearchFilters::default();
        let sort_pair = match sort {
            Some("create") | Some("newest") => Some(("create", "desc")),
            Some("create_asc") => Some(("create", "asc")),
            Some("credit") => Some(("credit", "desc")),
            Some("price_asc") => Some(("price", "asc")),
            Some("price_desc") | Some("price") => Some(("price", "desc")),
            _ => None,
        };
        if let Some((field, value)) = sort_pair {
            filters.sort_field = Some(field.to_string());
            filters.sort_value = Some(value.to_string());
        }
        filters.start_price = price_min.map(|s| s.to_string());
        filters.end_price = price_max.map(|s| s.to_string());
        let has_filters = sort_pair.is_some() || price_min.is_some() || price_max.is_some();
        let opts = SearchOptions {
            page_number: page,
            rows_per_page: limit,
            filters: if has_filters { Some(filters) } else { None },
            ..SearchOptions::default()
        };
        match build_search_request(Some(query), &opts) {
            Ok(plan) => self.execute_live(&plan).await,
            Err(e) => error_value("invalid_request", e.to_string()),
        }
    }

    /// Item detail. `product` is a numeric item id or a
    /// fleamarket/goofish URL containing one.
    pub async fn get_product(&self, product: &str) -> Value {
        let item_id = match extract_item_id(product) {
            Some(id) => id,
            None => {
                return error_value(
                    "invalid_request",
                    format!("no numeric item id found in {product:?}"),
                )
            }
        };
        match build_item_detail_request(&item_id, &DetailOptions::default()) {
            Ok(plan) => self.execute_live(&plan).await,
            Err(e) => error_value("invalid_request", e.to_string()),
        }
    }

    /// Search suggestions for a keyword; `entries` truncated to `limit`
    /// when limit > 0.
    pub async fn suggest_keywords(&self, keyword: &str, limit: usize) -> Value {
        let plan = match build_suggest_request(keyword, None, 0, None) {
            Ok(p) => p,
            Err(e) => return error_value("invalid_request", e.to_string()),
        };
        let mut result = self.execute_live(&plan).await;
        if limit > 0 && result.get("ok").and_then(|v| v.as_bool()) == Some(true) {
            if let Some(entries) = result
                .get_mut("data")
                .and_then(|d| d.get_mut("entries"))
                .and_then(|e| e.as_array_mut())
            {
                entries.truncate(limit);
            }
        }
        result
    }

    /// Public comments for an item. The comment.list request carries no
    /// page field in the app (rowsPerPage only), so `page` is accepted
    /// for interface symmetry and a single fetch is performed.
    pub async fn get_comments(&self, product: &str, page: i64) -> Value {
        let _ = page;
        let item_id = match extract_item_id(product) {
            Some(id) => id,
            None => {
                return error_value(
                    "invalid_request",
                    format!("no numeric item id found in {product:?}"),
                )
            }
        };
        match build_comment_list_request(&item_id, 10, None, None) {
            Ok(plan) => self.execute_live(&plan).await,
            Err(e) => error_value("invalid_request", e.to_string()),
        }
    }

    /// Related-item recommendations for an item.
    pub async fn get_recommendations(&self, product: &str) -> Value {
        let item_id = match extract_item_id(product) {
            Some(id) => id,
            None => {
                return error_value(
                    "invalid_request",
                    format!("no numeric item id found in {product:?}"),
                )
            }
        };
        let mut req_params = Map::new();
        req_params.insert("itemId".to_string(), json!(item_id));
        let mut opts = RecommendOptions::new();
        opts.req_params = Some(req_params);
        match build_recommend_request(&opts) {
            Ok(plan) => self.execute_live(&plan).await,
            Err(e) => error_value("invalid_request", e.to_string()),
        }
    }

    /// Home feed (nextfresh), one page.
    pub async fn home_feed(&self, page: i64) -> Value {
        let opts = HomeFeedOptions {
            page_number: page,
            ..HomeFeedOptions::default()
        };
        match build_home_feed_request(&opts) {
            Ok(plan) => self.execute_live(&plan).await,
            Err(e) => error_value("invalid_request", e.to_string()),
        }
    }
}

fn env_first(names: &[&str]) -> Option<String> {
    for name in names {
        if let Ok(value) = std::env::var(name) {
            if !value.is_empty() {
                return Some(value);
            }
        }
    }
    None
}

// ---------------------------------------------------------------------------
// Runtime resolution (zero-config by default)
//
// The user configures nothing. The two runtime pieces resolve as
// follows.
//
// Identity — an explicit override wins:
//   1. $GOOFISH_IDENTITY / $SHOPPING_MCP_GOOFISH_IDENTITY (path to a
//      JSON file {"utdid": ..., "device_id": ..., "ttid": ...})
//   2. the server-owned identity in the data directory
//      ($XDG_DATA_HOME/zero-search-mcp/goofish/identity.json,
//      default ~/.local/share/zero-search-mcp/...) — generated by
//      the server itself on first use with the app's own UTDID
//      algorithm (see the `identity` module) and reused after that
//   3. the `identity` key of a goofish.json config file
//   4. a bundle `identity.json`
// Steps 3–4 only matter for pre-ZeroSearch deployments; step 2 makes
// them unreachable in a fresh install.
//
// Signing serve command:
//   1. $GOOFISH_SG_SERVE / $SHOPPING_MCP_GOOFISH_SG_SERVE
//   2. the `sg_serve` key of the config file
//   3. an auto-discovered runtime *bundle*: a `goofish-runtime/`
//      directory next to the server executable (or the executable's
//      own directory) holding `serve.sh` (or `serve_lowmem.sh`), the
//      same directory under the server's data directory, or the
//      legacy `$HOME/.shopping-mcp/goofish-runtime/`.
// The bundle is part of the deployment, not a user setting: the MCP
// host configuration stays just the binary path. When no serve
// command resolves at all, live calls refuse with missing_runtime
// and send nothing.
//
// Config file (overrides only):
//   { "sg_serve": "/path/to/serve.sh", "identity": "/path/to/identity.json" }
// Lookup order for the file itself: $SHOPPING_MCP_GOOFISH_CONFIG
// (that file only, when set), then goofish.json next to the server
// executable, then $XDG_CONFIG_HOME/shopping-mcp/goofish.json
// (default ~/.config/shopping-mcp/goofish.json). Relative paths
// inside the file resolve against its directory (for `sg_serve`,
// only when the value is a single token; a command with arguments
// is used verbatim).
// ---------------------------------------------------------------------------

/// Parsed `goofish.json` runtime config file.
#[derive(Debug, Default, PartialEq)]
struct FileConfig {
    sg_serve: Option<String>,
    identity: Option<String>,
}

fn parse_file_config(text: &str, base_dir: &Path) -> Option<FileConfig> {
    let doc: Value = serde_json::from_str(text).ok()?;
    let obj = doc.as_object()?;
    let pick = |keys: &[&str]| -> Option<String> {
        keys.iter()
            .filter_map(|k| obj.get(*k))
            .filter_map(crate::util::as_str)
            .map(|s| s.trim().to_string())
            .find(|s| !s.is_empty())
    };
    let resolve_path = |value: String| -> String {
        let path = Path::new(&value);
        if path.is_relative() {
            base_dir.join(path).to_string_lossy().into_owned()
        } else {
            value
        }
    };
    let identity = pick(&["identity", "identity_file", "goofish_identity"]).map(resolve_path);
    // A serve *command* may carry arguments; only a bare single-token
    // path is resolved against the config file's directory.
    let sg_serve = pick(&["sg_serve", "serve", "goofish_sg_serve"]).map(|value| {
        if value.contains(char::is_whitespace) {
            value
        } else {
            resolve_path(value)
        }
    });
    Some(FileConfig { sg_serve, identity })
}

fn config_file_candidates() -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Ok(exe) = std::env::current_exe() {
        if let Some(dir) = exe.parent() {
            out.push(dir.join("goofish.json"));
        }
    }
    let config_home = std::env::var("XDG_CONFIG_HOME")
        .ok()
        .filter(|s| !s.is_empty())
        .map(PathBuf::from)
        .or_else(|| {
            std::env::var("HOME")
                .ok()
                .filter(|s| !s.is_empty())
                .map(|home| PathBuf::from(home).join(".config"))
        });
    if let Some(dir) = config_home {
        out.push(dir.join("shopping-mcp").join("goofish.json"));
    }
    out
}

fn load_file_config() -> Option<FileConfig> {
    if let Some(explicit) = env_first(&CONFIG_ENVS) {
        // An explicit config path is authoritative: default locations
        // are not searched as well.
        let path = PathBuf::from(&explicit);
        let text = std::fs::read_to_string(&path).ok()?;
        let base = path.parent().map(|p| p.to_path_buf()).unwrap_or_default();
        return parse_file_config(&text, &base);
    }
    for path in config_file_candidates() {
        if let Ok(text) = std::fs::read_to_string(&path) {
            let base = path.parent().map(|p| p.to_path_buf()).unwrap_or_default();
            if let Some(config) = parse_file_config(&text, &base) {
                return Some(config);
            }
        }
    }
    None
}

/// The resolved live runtime: overrides first (environment, then
/// the config file), then the zero-config defaults — the
/// server-generated identity and the auto-discovered bundle.
struct RuntimeSettings {
    identity_path: Option<String>,
    serve_command: Option<String>,
}

/// Runtime pieces found in one bundle directory: a serve script
/// (`serve.sh`, falling back to `serve_lowmem.sh`) and/or an
/// `identity.json`. Either piece may be absent.
fn bundle_in(dir: &Path) -> FileConfig {
    let serve = ["serve.sh", "serve_lowmem.sh"]
        .iter()
        .map(|name| dir.join(name))
        .find(|path| path.is_file());
    let identity_path = dir.join("identity.json");
    FileConfig {
        sg_serve: serve.map(|path| path.to_string_lossy().into_owned()),
        identity: if identity_path.is_file() {
            Some(identity_path.to_string_lossy().into_owned())
        } else {
            None
        },
    }
}

fn discover_bundle() -> FileConfig {
    let mut dirs: Vec<PathBuf> = Vec::new();
    if let Ok(exe) = std::env::current_exe() {
        if let Some(dir) = exe.parent() {
            dirs.push(dir.join("goofish-runtime"));
            dirs.push(dir.to_path_buf());
        }
    }
    if let Some(data) = identity::data_dir() {
        dirs.push(data.join("goofish-runtime"));
    }
    if let Some(home) = std::env::var("HOME").ok().filter(|s| !s.is_empty()) {
        dirs.push(
            PathBuf::from(home)
                .join(".shopping-mcp")
                .join("goofish-runtime"),
        );
    }
    let mut found = FileConfig::default();
    for dir in dirs {
        let bundle = bundle_in(&dir);
        if found.sg_serve.is_none() {
            found.sg_serve = bundle.sg_serve;
        }
        if found.identity.is_none() {
            found.identity = bundle.identity;
        }
        if found.sg_serve.is_some() && found.identity.is_some() {
            break;
        }
    }
    found
}

fn resolve_runtime() -> RuntimeSettings {
    let file = load_file_config().unwrap_or_default();
    let bundle = discover_bundle();
    RuntimeSettings {
        // The server-owned identity (auto-generated on first use)
        // outranks file/bundle identities so a fresh install always
        // lands on the managed document; explicit environment
        // overrides still win.
        identity_path: env_first(&IDENTITY_ENVS)
            .or_else(identity::load_or_create_identity)
            .or(file.identity)
            .or(bundle.identity),
        serve_command: env_first(&SERVE_ENVS).or(file.sg_serve).or(bundle.sg_serve),
    }
}

/// True when the signing serve command resolves (the identity is
/// server-generated on demand, so it is never the missing piece).
/// Used by the server e2e test to pick its expectation.
pub fn runtime_configured() -> bool {
    resolve_runtime().serve_command.is_some()
}

/// Split a serve command into program + arguments, honouring single
/// and double quotes and backslash escapes (shell-like tokenisation;
/// no variable or glob expansion). An empty/blank command yields an
/// empty vector.
fn split_serve_command(command: &str) -> Vec<String> {
    let mut parts = Vec::new();
    let mut current = String::new();
    let mut has_current = false;
    let mut quote: Option<char> = None;
    let mut chars = command.chars();
    while let Some(c) = chars.next() {
        match quote {
            Some(q) => {
                if c == q {
                    quote = None;
                } else if c == '\\' && q == '"' {
                    match chars.next() {
                        Some(esc @ ('"' | '\\')) => current.push(esc),
                        Some(other) => {
                            current.push('\\');
                            current.push(other);
                        }
                        None => current.push('\\'),
                    }
                } else {
                    current.push(c);
                }
            }
            None => match c {
                '\'' | '"' => {
                    quote = Some(c);
                    has_current = true;
                }
                '\\' => {
                    has_current = true;
                    match chars.next() {
                        Some(esc) => current.push(esc),
                        None => current.push('\\'),
                    }
                }
                c if c.is_whitespace() => {
                    if has_current {
                        parts.push(std::mem::take(&mut current));
                        has_current = false;
                    }
                }
                _ => {
                    has_current = true;
                    current.push(c);
                }
            },
        }
    }
    if has_current {
        parts.push(current);
    }
    parts
}

/// Extract a numeric item id from a bare id or a fleamarket/goofish URL.
pub fn extract_item_id(product: &str) -> Option<String> {
    let trimmed = product.trim();
    if !trimmed.is_empty() && trimmed.chars().all(|c| c.is_ascii_digit()) {
        return Some(trimmed.to_string());
    }
    let by_param = regex::Regex::new(r"[?&]id=(\d+)").ok()?;
    if let Some(cap) = by_param.captures(trimmed) {
        return Some(cap[1].to_string());
    }
    let re = regex::Regex::new(r"\d{4,}").ok()?;
    re.find(trimmed).map(|m| m.as_str().to_string())
}

/// application/x-www-form-urlencoded encoding (quote_plus semantics:
/// unreserved bytes kept, space -> '+', everything else %XX).
fn percent_encode(value: &str) -> String {
    let mut out = String::with_capacity(value.len());
    for byte in value.bytes() {
        match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(byte as char)
            }
            b' ' => out.push('+'),
            _ => out.push_str(&format!("%{byte:02X}")),
        }
    }
    out
}

